"""Plain-language interpretation attached to the existing result pages."""
def intro(kind):
    flow='''<nav class="presentation-flow" aria-label="Project presentation sequence"><a href="demo.html"><span>01</span> Run the live image</a><a href="robustness.html"><span>02</span> Test source sensitivity</a><a href="results.html"><span>03</span> Explain the measured results</a><a href="contribution.html"><span>04</span> Explain our contribution</a></nav>'''
    guide='''<section class="metric-primer tight"><div class="wrap">'''+flow+'''<div class="score-guide"><article><span>ONE IMAGE</span><h2>Confidence</h2><p>The model's largest softmax output. A 95% reading does not mean 95% accuracy or a 95% chance of being right.</p></article><article><span>MANY LABELLED IMAGES</span><h2>Balanced accuracy</h2><p>Find recall separately for Hip, Knee and Shoulder, then average the class recalls. A score of 0.686 means 68.6% balanced accuracy.</p></article><article><span>TWO TEST SETTINGS</span><h2>Generalization gap</h2><p>Subtract source-controlled balanced accuracy from pooled balanced accuracy. 0.9982 − 0.6859 = 0.3123, a 31.23 percentage-point drop.</p></article></div>'''
    if kind=='robustness':
        guide+='''<div class="presentation-note"><b>How to demonstrate this page</b><p>1. Compare pooled and source-controlled scenarios. 2. Select EfficientNet-B3 and explain the score drop. 3. Select Image dimensions (RF): it falls to chance without seeing anatomy. 4. Open Results for intervals and supporting tests.</p><p>The pooled endpoint uses 657 test images; the decoupled endpoint uses the 55-image FracAtlas test subset. These are separate checkpoints trained under different source protocols. The same-image control is available on the Results page.</p></div>'''
    else:
        guide+='''<div class="presentation-note"><b>Read the results in this order</b><p><strong>1. Pooled vs controlled:</strong> the main comparison, sensitivity checks and class errors. <strong>2. Source holdouts:</strong> which sources transfer. <strong>3. Shortcut probes:</strong> can simple cues predict the joint? <strong>4. OOD &amp; calibration:</strong> can confidence identify unfamiliar or incorrect inputs?</p><p>Blue marks pooled testing and orange marks source-controlled testing where shown in the legend. Error bars show uncertainty, not per-image confidence. Use “View as table” for exact values. On smaller screens, scroll within a chart to keep labels readable.</p></div>'''
    return guide+'''<div class="explanation-downloads"><a href="downloads/context.md">Download the complete project explanation ↗</a><a href="downloads/literaturesurvey.md">Download the literature survey ↗</a></div></div></section>'''
